// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAccounts Every account on this instance
	// (GET /accounts)
	ListAccounts(ctx context.Context, request ListAccountsRequestObject) (ListAccountsResponseObject, error)
	// CreateAccount Make an account for a person
	// (POST /accounts)
	CreateAccount(ctx context.Context, request CreateAccountRequestObject) (CreateAccountResponseObject, error)
	// DeactivateAccount Stop an account from signing in
	// (DELETE /accounts/{accountId})
	DeactivateAccount(ctx context.Context, request DeactivateAccountRequestObject) (DeactivateAccountResponseObject, error)
	// GetHealth Report whether the service is able to serve
	// (GET /health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// WhoAmI Who this request resolves to
	// (GET /me)
	WhoAmI(ctx context.Context, request WhoAmIRequestObject) (WhoAmIResponseObject, error)
	// ListProjects The projects this caller may see
	// (GET /projects)
	ListProjects(ctx context.Context, request ListProjectsRequestObject) (ListProjectsResponseObject, error)
	// CreateProject Open a book
	// (POST /projects)
	CreateProject(ctx context.Context, request CreateProjectRequestObject) (CreateProjectResponseObject, error)
	// GetProject Read a project
	// (GET /projects/{slug})
	GetProject(ctx context.Context, request GetProjectRequestObject) (GetProjectResponseObject, error)
	// ListAxes Read the project's rendering axes, in their declared order
	// (GET /projects/{slug}/axes)
	ListAxes(ctx context.Context, request ListAxesRequestObject) (ListAxesResponseObject, error)
	// OrderAxes Declare the order the axes read in
	// (PUT /projects/{slug}/axes)
	OrderAxes(ctx context.Context, request OrderAxesRequestObject) (OrderAxesResponseObject, error)
	// HeadBlob Report whether the store already holds this content
	// (HEAD /projects/{slug}/blobs/{hash})
	HeadBlob(ctx context.Context, request HeadBlobRequestObject) (HeadBlobResponseObject, error)
	// PutBlob Store content under its address
	// (PUT /projects/{slug}/blobs/{hash})
	PutBlob(ctx context.Context, request PutBlobRequestObject) (PutBlobResponseObject, error)
	// GetCaptureImage The image a capture holds
	// (GET /projects/{slug}/captures/{captureId})
	GetCaptureImage(ctx context.Context, request GetCaptureImageRequestObject) (GetCaptureImageResponseObject, error)
	// ListCases List the catalogue
	// (GET /projects/{slug}/cases)
	ListCases(ctx context.Context, request ListCasesRequestObject) (ListCasesResponseObject, error)
	// CreateCase Open a case and receive its id
	// (POST /projects/{slug}/cases)
	CreateCase(ctx context.Context, request CreateCaseRequestObject) (CreateCaseResponseObject, error)
	// GetCase Read a case, archived or not
	// (GET /projects/{slug}/cases/{caseId})
	GetCase(ctx context.Context, request GetCaseRequestObject) (GetCaseResponseObject, error)
	// UpdateCase Change what is mutable about a case
	// (PATCH /projects/{slug}/cases/{caseId})
	UpdateCase(ctx context.Context, request UpdateCaseRequestObject) (UpdateCaseResponseObject, error)
	// ArchiveCase Take a case out of the catalogue
	// (POST /projects/{slug}/cases/{caseId}/archive)
	ArchiveCase(ctx context.Context, request ArchiveCaseRequestObject) (ArchiveCaseResponseObject, error)
	// GetCaseCaptures Read the evidence a case is judged from
	// (GET /projects/{slug}/cases/{caseId}/captures)
	GetCaseCaptures(ctx context.Context, request GetCaseCapturesRequestObject) (GetCaseCapturesResponseObject, error)
	// ListComments Read what has been said about a case
	// (GET /projects/{slug}/cases/{caseId}/comments)
	ListComments(ctx context.Context, request ListCommentsRequestObject) (ListCommentsResponseObject, error)
	// SaveReview Save what one review session decided
	// (POST /projects/{slug}/cases/{caseId}/reviews)
	SaveReview(ctx context.Context, request SaveReviewRequestObject) (SaveReviewResponseObject, error)
	// ListCategories Read the catalogue tree
	// (GET /projects/{slug}/categories)
	ListCategories(ctx context.Context, request ListCategoriesRequestObject) (ListCategoriesResponseObject, error)
	// CreateCategory Add a node to the tree
	// (POST /projects/{slug}/categories)
	CreateCategory(ctx context.Context, request CreateCategoryRequestObject) (CreateCategoryResponseObject, error)
	// DeleteCategory Remove an empty node
	// (DELETE /projects/{slug}/categories/{categoryId})
	DeleteCategory(ctx context.Context, request DeleteCategoryRequestObject) (DeleteCategoryResponseObject, error)
	// DeliverComment Ask for a judgment on a delivered fix
	// (POST /projects/{slug}/comments/{commentId}/delivery)
	DeliverComment(ctx context.Context, request DeliverCommentRequestObject) (DeliverCommentResponseObject, error)
	// DiscardComment Set a comment aside
	// (POST /projects/{slug}/comments/{commentId}/discard)
	DiscardComment(ctx context.Context, request DiscardCommentRequestObject) (DiscardCommentResponseObject, error)
	// JudgeComment Accept a delivery, or refuse it
	// (POST /projects/{slug}/comments/{commentId}/judgment)
	JudgeComment(ctx context.Context, request JudgeCommentRequestObject) (JudgeCommentResponseObject, error)
	// TrackComment Attach an external issue to a comment
	// (POST /projects/{slug}/comments/{commentId}/reference)
	TrackComment(ctx context.Context, request TrackCommentRequestObject) (TrackCommentResponseObject, error)
	// CreateEdition Take a run's evidence into the book
	// (POST /projects/{slug}/editions)
	CreateEdition(ctx context.Context, request CreateEditionRequestObject) (CreateEditionResponseObject, error)
	// ListMembers Who reaches this project
	// (GET /projects/{slug}/members)
	ListMembers(ctx context.Context, request ListMembersRequestObject) (ListMembersResponseObject, error)
	// RevokeMembership Take a person off a project
	// (DELETE /projects/{slug}/members/{accountId})
	RevokeMembership(ctx context.Context, request RevokeMembershipRequestObject) (RevokeMembershipResponseObject, error)
	// GrantMembership Put a person on a project, or change what they may do
	// (PUT /projects/{slug}/members/{accountId})
	GrantMembership(ctx context.Context, request GrantMembershipRequestObject) (GrantMembershipResponseObject, error)
	// GetRecordingVideo The video a recording holds
	// (GET /projects/{slug}/recordings/{recordingId})
	GetRecordingVideo(ctx context.Context, request GetRecordingVideoRequestObject) (GetRecordingVideoResponseObject, error)
	// CreateServiceAccount Make a program an account on this project
	// (POST /projects/{slug}/service-accounts)
	CreateServiceAccount(ctx context.Context, request CreateServiceAccountRequestObject) (CreateServiceAccountResponseObject, error)
	// DeactivateServiceAccount Retire a program
	// (DELETE /projects/{slug}/service-accounts/{serviceAccountId})
	DeactivateServiceAccount(ctx context.Context, request DeactivateServiceAccountRequestObject) (DeactivateServiceAccountResponseObject, error)
	// ListServiceTokens What tokens this program holds
	// (GET /projects/{slug}/service-accounts/{serviceAccountId}/tokens)
	ListServiceTokens(ctx context.Context, request ListServiceTokensRequestObject) (ListServiceTokensResponseObject, error)
	// MintServiceToken Mint another token for this program
	// (POST /projects/{slug}/service-accounts/{serviceAccountId}/tokens)
	MintServiceToken(ctx context.Context, request MintServiceTokenRequestObject) (MintServiceTokenResponseObject, error)
	// RetireServiceToken Stop one token working
	// (DELETE /projects/{slug}/service-accounts/{serviceAccountId}/tokens/{tokenId})
	RetireServiceToken(ctx context.Context, request RetireServiceTokenRequestObject) (RetireServiceTokenResponseObject, error)
	// RequestSignIn Ask for a sign-in link
	// (POST /sign-in)
	RequestSignIn(ctx context.Context, request RequestSignInRequestObject) (RequestSignInResponseObject, error)
	// ClaimSignIn Spend a sign-in link and open a session
	// (POST /sign-in/claim)
	ClaimSignIn(ctx context.Context, request ClaimSignInRequestObject) (ClaimSignInResponseObject, error)
	// SignOut End this session
	// (POST /sign-out)
	SignOut(ctx context.Context, request SignOutRequestObject) (SignOutResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// ListAccounts operation middleware
